UPDATE product_inventory
SET import_price = #{importPrice},
    quantity     = #{quantity}
WHERE product_id = #{productId}

mapper.sql:
productFilter as(
SELECT p.id
FROM product p

    INNER JOIN category_product cp ON p.id = cp.product_id
    WHERE cp.category_id IN

        #{categoryId}

    GROUP BY p.id HAVING COUNT(p.id) = #{listCategoryIds.size()}

)

